<template>
<div class="my-popups">
    <loader :is-visible="isLoading"></loader>

    <div class="modal my-popups right fade d-block" :class="{ show: isShown }">
        <div role="document" class="modal-dialog" style="max-width: 1000px !important;">
            <div class="modal-content">
                <div class="modal-header theme-primary partition-full d-flex">
                    <h4 class="modal-title">{{ $t('AvailableContracts') }}</h4>
                    <button type="button" class="close" v-on:click="Close">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>
                </div>

                <div class="modal-body">

                    <div class="tab-content">
                     <div class="tab-pane active show">
                         <div class="pt-2 d-inline-block w-100">
                        <div class="col-12 p-0 mt-0">
                            <div class="col-6 col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pr-1 pl-0">
                                <input id="txtSelectedColumnsInSetup"  @keyup.enter="SearchButton(Searchtext)" maxlength="50" class="form-control" type="text" v-model="Searchtext" placeholder="Search by Contract Name." autocomplete="off">
                            </div>
                            <div class="col-6 col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pl-0">
                                <div class="search-btm-btn background-0  form-check-inline">
                                    <button title="Search" @click="SearchButton(Searchtext)"  class="btn btn-success mr-1 px-4" data-original-title="Search">
                                        <em class="fa fa-search"></em> Search
                                    </button>
                                    <button title="Clear" class="btn btn-danger px-4" @click="Clear()" data-original-title="Clear">
                                        <em class="fa fa-refresh"></em> Clear
                                    </button>
                                </div>
                            </div>
                        </div>
                         </div>
     
                         <div class="listing">
                        <div class="table-responsive table-fix-header">
                            <table class="table table-bordered">
                                <thead class="thead-bg">
                                    <tr>
                                        <th style="width:5%" class="text-center">
                                            <label class="form-check form-check-inline">
                                                <div class="custom-control custom-checkbox custom-control-inline">
                                                    <input type="checkbox" id="talygenAssetCheckAll" class="chkitems1 custom-control-input" :checked="selectAll" @change="selectAllItems" name="selectedItems1">
                                                    <label class="custom-control-label" for="talygenAssetCheckAll"></label>
                                                </div>
                                            </label>
                                        </th>
                                        <th scope="col" class="cursor-pointer" @click="sortdata('CHILD_NAME')">
                                            <div class="d-flex justify-content-between align-items-center">
                                                <span>{{ $t("CONTRACTNAME") }}</span>
                                                <span><em class="fa" :class="SortBy === 'CHILD_NAME' ? (SortExp === 'ASC' ? 'fa-sort-up' : 'fa-sort-down') : 'fa-sort'"></em></span>
                                            </div>
                                        </th>

                                    </tr>
                                </thead>
                                <tbody>
                                    <!-- {{ContractData}} -->
                                    <tr v-for="(item,index) in ContractData" :key="index">
                                        <td class="text-center">
                                            <label class="form-check form-check-inline">
                                                <div class="custom-control custom-checkbox custom-control-inline">
                                                    <input type="checkbox" :id="'tabletablebordered' + index" class="chkitems custom-control-input" v-model="selectedItems" @change="updateSelectAll" name="selectedItems" :value="item.CHILD_USER_ID">
                                                    <label :for="'tabletablebordered' + index" class="custom-control-label"></label>
                                                </div>
                                            </label>
                                        </td>

                                        <td>
                                            <div class="text" :title="stripHtml(item.CHILD_NAME)" v-html="item.CHILD_NAME"> </div>
                                            
                                        </td>
                                    </tr>

                                    <tr v-if="!ContractData || ContractData.length === 0">
                                        <td colspan="6" class="text-danger text-center border-0">
                                            {{ $t("NorecordfoundText") }}
                                        </td>
                                    </tr>

                                </tbody>
                                
                            </table>
                        </div>

                        <dynamic-form lang="en" ref="AvailableContract" :buttons="buttons" :schema="FormSchema" v-on:OnSubmit="onSubmit" :mandatorytext='MandatoryString'>
                        </dynamic-form>
                         </div>
                        <!-- <section class="available-cont">
                        <tg-list :IsShowAction="false" ModuleName="Billing" SubModuleCode="Billing" :LegendArray="[]" :RenderRowActionMethod="renderActions" 
                        v-on:ActionButtonClick="actionButtonClick" :widgets="[]" IdentityColumn="CHILD_USER_ID" :listType="['List']" :ListData="ContractData" 
                        :HeaderData="Headers" :HeaderButtons="listheaderbuttons" :TotalRecords="TotalRecords" :SearchFields="topSearchFields" :IsSearchFieldsOnTop="true" 
                        SearchPosition="top" :ListDataCallBackFunction="GetAvailableContracts" :showCheckBox="true" :SortExp="SortExp" :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')" 
                        :HeaderText="$t('')" v-on:LeftsearchButtonClick="leftCommonSearch" v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
                         v-on:SortdataButtonClick="sortdata" :routeInfo="$router">
                            <template v-slot:slotdata="{ data }">
                                <template v-if="data.column.COLUMN_NAME === 'CHILD_NAME'">
                                    <div class="text"  :title="data.row.CHILD_NAME"
                                        v-html="data.row.CHILD_NAME">
                                    </div>
                                </template>
                            </template>
                        </tg-list>
                        <dynamic-form lang="en" ref="AvailableContract" :buttons="buttons" :schema="FormSchema" v-on:OnSubmit="onSubmit" :mandatorytext='MandatoryString'>
                        </dynamic-form>
                    </section> -->
                
                   </div>
                    </div>
                
                
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from '../../services/DataService';

export default {
    components: {},
     props: {
        billerId: {
            type: Number,
            required: false,
        },
        /** CHILD_USER_IDs already on the Assign Biller grid — omitted until that row is deleted */
        excludeChildUserIds: {
            type: Array,
            default: () => []
        }
    },
    watch: {
        excludeChildUserIds: {
            deep: true,
            handler() {
                this.applyPagedView();
            }
        }
    },
    data() {
        return {
            listheaderbuttons: [],
            listActions: [],
            isLoading: false,
            isShown: false,
            ContractData: [],
            allContractsRaw: [],
            selectedItems: [],
            selectAll: false,
            AssignBiller: [],
            SortBy: '',
            SortExp: '',

            noRecords: false,
            searchCondition: '',
            Searchtext: '',
            FormSchema: [],
            topSearchFields: [{
                fieldName: 'Search by Contract Name.',
                fieldType: "text",
                fieldSearchConditionName: [''],
                paramName: "ContractName",
                isSearch: true,
                value: "",
                listOptions: []
            }],
            Headers: [{
                "COLUMN_NAME": "CHILD_NAME",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": 'Contract Name',
                "DISPLAY_ORDER": 1,
                settings: {
                    isInSlot: true
                }
            }, ],
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            buttons: [{
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Next",
                    isVisible: true
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.Close
                }
            ]
        };
    },
    mounted() {
        this.isShown = true; // show modal immediately — no delay
    },
    created: async function () {
        await this.loadContractsBulk();
        this.applyPagedView();
    },
    methods: {
        stripHtml(s) {
            if (!s) return '';
            return String(s).replace(/<[^>]+>/g, ' ');
        },
        async loadContractsBulk(searchText = '') {
            const vm = this;
            vm.isLoading = true;
            try {
                const bid = vm.billerId != null && vm.billerId !== '' ? vm.billerId : '';
                const encodedSearch = encodeURIComponent((searchText || '').trim());
                // Use pageSize=500 and server-side search= for fast loading
                const url = `pageNum=1&pageSize=1000000&reqFrom=MANAGEBILLER&search=${encodedSearch}&userId=&screenName=&billerId=${bid}`;
                const response = await DataService.GetAvailableContracts(url);
                let rows = response?.data?.result;
                if (!rows) {
                    vm.allContractsRaw = [];
                    return;
                }
                if (!Array.isArray(rows)) {
                    rows = [rows];
                }
                vm.allContractsRaw = rows.filter(r => r && r.CHILD_USER_ID != null);
            } catch (e) {
                console.error('AvailableContract loadContractsBulk:', e);
                vm.allContractsRaw = [];
            } finally {
                vm.isLoading = false;
            }
        },
        getFilteredList() {
            let list = (this.allContractsRaw || []).filter(x => x && x.CHILD_USER_ID != null);
            // Exclude already-assigned contracts
            const ex = new Set((this.excludeChildUserIds || []).map(id => Number(id)).filter(n => !isNaN(n)));
            if (ex.size) {
                list = list.filter(c => !ex.has(Number(c.CHILD_USER_ID)));
            }
            // Client-side text filter as fallback (server search is primary)
            const q = (this.searchCondition || '').trim().toLowerCase();
            if (q) {
                list = list.filter(c => {
                    const raw = (c.CHILD_NAME || '').toString();
                    const plain = raw.replace(/<[^>]+>/g, ' ').toLowerCase();
                    return plain.includes(q) || raw.toLowerCase().includes(q);
                });
            }
            if (this.SortBy === 'CHILD_NAME') {
                const dir = this.SortExp === 'ASC' ? 1 : -1;
                list = [...list].sort((a, b) => {
                    const nameA = (a.CHILD_NAME || '').toString().replace(/<[^>]+>/g, '').toLowerCase();
                    const nameB = (b.CHILD_NAME || '').toString().replace(/<[^>]+>/g, '').toLowerCase();
                    if (nameA < nameB) return -1 * dir;
                    if (nameA > nameB) return 1 * dir;
                    return 0;
                });
            }
            return list;
        },
        applyPagedView() {
            const vm = this;
            const list = vm.getFilteredList();
            vm.ContractData = list;
            vm.updateSelectAll();
        },
        GetAvailableContracts() {
            this.applyPagedView();
        },

        SearchButton(txt) {
            var vm = this;
            const searchText = (txt != null ? String(txt) : vm.Searchtext || '').trim();
            vm.searchCondition = searchText;
            // Re-fetch from server with the search term for fast server-side filtering
            vm.loadContractsBulk(searchText).then(() => vm.applyPagedView());
        },

        Clear() {
            var vm = this;
            vm.Searchtext = '';
            vm.searchCondition = '';
            // Reload unfiltered initial records
            vm.loadContractsBulk('').then(() => vm.applyPagedView());
        },

        selectAllItems() {
            var vm = this;
            vm.selectAll = !vm.selectAll;
            if (vm.selectAll) {
                vm.ContractData.forEach(function (item) {
                    const uid = item.CHILD_USER_ID;
                    if (!vm.selectedItems.some(s => Number(s) === Number(uid))) {
                        vm.selectedItems.push(uid);
                    }
                });
            } else {
                const pageIds = vm.ContractData.map(x => Number(x.CHILD_USER_ID));
                vm.selectedItems = vm.selectedItems.filter(id => !pageIds.includes(Number(id)));
            }
        },
        updateSelectAll() {
            var vm = this;
            const totalItems = vm.ContractData.length;
            if (!totalItems) {
                vm.selectAll = false;
                return;
            }
            const selectedOnPage = vm.ContractData.filter(x =>
                vm.selectedItems.some(s => Number(s) === Number(x.CHILD_USER_ID))
            ).length;
            vm.selectAll = selectedOnPage === totalItems;
        },

        onSubmit(formfields) {
            var vm = this;
            vm.buttons[0].class = 'btn btn-success disabled'; // prevent double-submit
            const set = new Set(vm.selectedItems.map(id => Number(id)));
            vm.AssignBiller = vm.allContractsRaw.filter(x => set.has(Number(x.CHILD_USER_ID)));
            const payload = {
                formfields: formfields,
                AssignBiller: vm.AssignBiller
            };
            vm.$emit('submit-data', payload);
            vm.$parent.isAddContract = false;
        },


       

        Close() {
            this.$parent.isAddContract = false;
        },

        leftCommonSearch: function (value) {

        },
        commonHeaderButtonClick: function (event) {
            switch (event.callbackfunction) {

            }
        },
        sortdata: function (sortBy) {
            this.SortBy = sortBy;
            var sortExp = 'ASC';
            if (this.SortExp == 'ASC') {
                sortExp = 'DESC';
            }
            this.SortExp = sortExp;
            this.applyPagedView();
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            //this.FetchData();
        },
        renderActions: function (row) {
            var self = this;
            let rtnActionArray = [];
            // self.listActions.forEach(actionItem => {
            //     let action = {
            //         ...actionItem
            //     };
            //     switch (action.title) {

            //     }
            //     rtnActionArray.push(action);
            // });
            return rtnActionArray;
        },
        actionButtonClick: function (callbackfunction, item) {
            switch (callbackfunction) {

            }
        },
    }
};
</script>

