<template>
<section>
    <loader :is-visible="isLoading"></loader>
    <div class="modal my-popups right fade d-block" :class="{ show: isShown }">
        <div role="document" class="modal-dialog" style="max-width: 1300px !important;">
            <div class="modal-content">
                <div class="modal-header theme-primary partition-full d-flex">
                    <h4 class="modal-title">
                        {{ modalTitle }}
                        <small v-if="entityName" class="ml-2 text-white-50">- {{ entityName }}</small>
                    </h4>
                    <button type="button" class="close" v-on:click="Close">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>
                </div>

                <div class="modal-body">
                    <div class="tab-content">
                        <div class="tab-pane active show">

                            <div class="col-12 p-0">
                                <div class="row m-0 mb-2">
                                    <div class="col-12 col-sm-6 col-md-3 col-lg-3 mb-2 pl-0">
                                        <label class="form-label small mb-1">{{ $t('From') || 'From' }}</label>
                                        <div class="input-group">
                                            <v-date-picker id="historyDateFrom" mode="date" class="timedate input-group"
                                                v-model="filters.fromDate" :popover="{ visibility: 'click' }"
                                                :masks="dateMasks">
                                                <template v-slot="{ inputValue, inputEvents, togglePopover }">
                                                    <input placeholder="M/D/YYYY" @click="togglePopover()"
                                                        class="form-control"
                                                        :value="inputValue" v-on="inputEvents" autocomplete="off" />
                                                    <div @click="togglePopover()" class="input-group-append">
                                                        <span class="input-group-text"><em class="fa fa-calendar"></em></span>
                                                    </div>
                                                </template>
                                            </v-date-picker>
                                        </div>
                                    </div>
                                    <div class="col-12 col-sm-6 col-md-3 col-lg-3 mb-2 pl-0">
                                        <label class="form-label small mb-1">{{ $t('To') || 'To' }}</label>
                                        <div class="input-group">
                                            <v-date-picker id="historyDateTo" mode="date" class="timedate input-group"
                                                v-model="filters.toDate" :popover="{ visibility: 'click' }"
                                                :masks="dateMasks">
                                                <template v-slot="{ inputValue, inputEvents, togglePopover }">
                                                    <input placeholder="M/D/YYYY" @click="togglePopover()"
                                                        class="form-control"
                                                        :value="inputValue" v-on="inputEvents" autocomplete="off" />
                                                    <div @click="togglePopover()" class="input-group-append">
                                                        <span class="input-group-text"><em class="fa fa-calendar"></em></span>
                                                    </div>
                                                </template>
                                            </v-date-picker>
                                        </div>
                                    </div>
                                    <div class="col-12 col-sm-6 col-md-3 col-lg-3 mb-2 pl-0">
                                        <label class="form-label small mb-1">{{ $t('ActionType') || 'Action Type' }}</label>
                                        <select class="form-control" v-model="filters.actionType" @change="applyFilters">
                                            <option value="">{{ $t('All') || 'All' }}</option>
                                            <option v-for="opt in actionTypeOptions" :key="opt" :value="opt">{{ opt }}</option>
                                        </select>
                                    </div>
                                    <div class="col-12 col-sm-6 col-md-3 col-lg-3 mb-2 pl-0">
                                        <label class="form-label small mb-1">{{ $t('User') || 'User' }}</label>
                                        <select class="form-control" v-model="filters.userId" @change="applyFilters">
                                            <option value="">{{ $t('All') || 'All' }}</option>
                                            <option v-for="u in userOptions" :key="u.id" :value="u.id">{{ u.name }}</option>
                                        </select>
                                    </div>
                                </div>

                                <div class="row m-0 mb-2">
                                    <div class="col-12 col-sm-8 col-md-8 col-lg-9 pl-0">
                                        <input type="text" class="form-control" maxlength="100"
                                            v-model="filters.searchText"
                                            :placeholder="searchPlaceholder"
                                            @input="applyFilters"
                                            @keyup.enter="applyFilters" autocomplete="off">
                                    </div>
                                    <div class="col-12 col-sm-4 col-md-4 col-lg-3 pl-0 mt-2 mt-sm-0">
                                        <!-- <button type="button" class="btn btn-success mr-1 px-3" @click="applyFilters">
                                            <em class="fa fa-search"></em> {{ $t('Search') || 'Search' }}
                                        </button> -->
                                        <button type="button" class="btn btn-danger px-3" @click="ClearFilters">
                                            <em class="fa fa-refresh"></em> {{ $t('Clear') || 'Clear' }}
                                        </button>
                                    </div>
                                </div>
                            </div>

                            <div class="listing mt-2">
                                <div class="table-responsive table-fix-header" style="max-height: calc(100vh - 320px); overflow-y: auto;">
                                    <table class="table table-bordered dt-responsive nowrap mt-0 mb-0" style="width:100%">
                                        <thead class="thead-bg">
                                            <tr>
                                                <th style="width:22%">{{ $t('DateTime') || 'Date & Time' }}</th>
                                                <th style="width:14%">{{ $t('ActionType') || 'Action Type' }}</th>
                                                <th style="width:30%">{{ entityColumnHeader }}</th>
                                                <th style="width:22%">{{ $t('CreatedBy') || 'Created By' }}</th>
                                                <th class="text-center" style="width:12%">{{ $t('View') || 'View' }}</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            <tr v-for="(row, index) in filteredData" :key="rowKey(row, index)">
                                                <td>
                                                    <span v-if="row.CHANGED_AT">{{ formatDateTime(row.CHANGED_AT) }}</span>
                                                    <span v-else>--</span>
                                                </td>
                                                <td>
                                                    <span class="text-white px-2 py-1 d-block text-center" :class="actionBadgeClass(row.ACTION_TYPE)">
                                                        {{ row.ACTION_TYPE || '--' }}
                                                    </span>
                                                </td>
                                                <td :title="entityNameOf(row)">{{ entityNameOf(row) || '--' }}</td>
                                                <td>{{ row.CHANGED_BY_NAME || row.CHANGED_BY || '--' }}</td>
                                                <td class="text-center single-action">
                                                    <a href="javascript:;" class="action-icon" data-toggle-tooltip="tooltip"
                                                        :title="$t('ViewDetails') || 'View Details'" @click="OpenDetails(row)">
                                                        <em class="fa fa-eye text-info"></em>
                                                    </a>
                                                </td>
                                            </tr>
                                            <tr v-if="!filteredData || filteredData.length === 0">
                                                <td colspan="5" class="text-danger text-center no-record">
                                                    {{ $t('NoRecordfound') || 'No history records found' }}
                                                </td>
                                            </tr>
                                        </tbody>
                                    </table>
                                </div>
                            </div>

                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <div v-if="isDetailsOpen" class="modal my-popups fade d-block show" style="background: rgba(0,0,0,0.5);">
        <div role="document" class="modal-dialog modal-lg" style="max-width: 1100px;">
            <div class="modal-content">
                <div class="modal-header theme-primary partition-full d-flex">
                    <h5 class="modal-title">
                        {{ $t('ChangeDetails') || 'Change Details' }}
                        <small v-if="selectedRow && selectedRow.CHANGED_AT" class="ml-2 text-white-50">
                            - {{ formatDateTime(selectedRow.CHANGED_AT) }}
                        </small>
                    </h5>
                    <button type="button" class="close" v-on:click="CloseDetails">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>
                </div>

                <div class="modal-body">
                <div v-if="selectedRow" class="row mb-3 ">
                    <div class="col-sm-12 col-md-4 col-lg-4 bg-light py-2" v-if="selectedRow.BILLER_NAME">
                        <strong>{{ $t('Biller') || 'Biller' }}:</strong>
                        <span class="ml-1">{{ selectedRow.BILLER_NAME }}</span>
                    </div>
                    <div class="col-sm-12 col-md-4 col-lg-4 bg-light py-2" v-if="selectedRow.CONTRACT_NAME">
                        <strong>{{ $t('Contract') || 'Contract' }}:</strong>
                        <span class="ml-1">{{ formatContractWithNumber(selectedRow.CONTRACT_NAME, selectedRow.CONTRACT_NO) }}</span>
                    </div>
                    <div class="col-sm-12 col-md-4 col-lg-4 bg-light py-2" v-if="selectedRow.CHANGED_BY_NAME || selectedRow.CHANGED_BY">
                        <strong>{{ $t('CreatedBy') || 'Created By' }}:</strong>
                        <span class="ml-1">{{ selectedRow.CHANGED_BY_NAME || selectedRow.CHANGED_BY }}</span>
                    </div>
                </div>

                
                    <div class="row m-0">
                        <div class="col-12 col-md-6 pl-0 pr-md-2 mb-3">
                            <div class="heading-border mb-2">
                                <h5 class="h5 mb-0"><span>{{ $t('Before') || 'Before' }}</span></h5>
                            </div>
                            <div class="listing">
                            <div class="table-responsive table-fix-header float-left" style="min-height: 200px; max-height: 400px; overflow-y: auto;">
                                <table v-if="beforeRows.length" class="table table-bordered mt-0">
                                    <thead>
                                        <tr>
                                            <th style="width:40%">{{ $t('Field') || 'Field' }}</th>
                                            <th>{{ $t('Value') || 'Value' }}</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        <tr v-for="(item, idx) in beforeRows" :key="'before-' + idx"
                                            :class="{ 'table-warning': isChanged(item.key) }">
                                            <td><strong>{{ item.key }}</strong></td>
                                            <td>{{ item.value }}</td>
                                        </tr>
                                    </tbody>
                                </table>
                                <pre v-else class="mb-0 small">{{ rawBefore || '--' }}</pre>
                            </div>
                            </div>
                        </div>
                        <div class="col-12 col-md-6 pl-0 pr-0 mb-3">
                            <div class="heading-border mb-2">
                                <h5 class="h5 mb-0"><span>{{ $t('After') || 'After' }}</span></h5>
                            </div>
                            <div class="listing">
                            <div class="table-responsive table-fix-header float-left" style="min-height: 200px; max-height: 400px; overflow-y: auto;">
                                <table v-if="afterRows.length" class="table table-bordered mt-0">
                                    <thead>
                                        <tr>
                                            <th style="width:40%">{{ $t('Field') || 'Field' }}</th>
                                            <th>{{ $t('Value') || 'Value' }}</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        <tr v-for="(item, idx) in afterRows" :key="'after-' + idx"
                                            :class="{ 'table-success': isChanged(item.key) }">
                                            <td><strong>{{ item.key }}</strong></td>
                                            <td>{{ item.value }}</td>
                                        </tr>
                                    </tbody>
                                </table>
                                <pre v-else class="mb-0 small">{{ rawAfter || '--' }}</pre>
                            </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-danger" @click="CloseDetails">
                        <em class="fa fa-close pr-2"></em>{{ $t('Close') || 'Close' }}
                    </button>
                </div>
            </div>
        </div>
    </div>
</section>
</template>

<script>
import DataService from '../../services/DataService';

export default {
    props: {
        entityId: {
            type: [Number, String],
            required: true
        },
        moduleType: {
            type: String,
            required: true,
            default: 'Biller'
        },
        entityName: {
            type: String,
            required: false,
            default: ''
        }
    },
    data() {
        return {
            isLoading: false,
            isShown: false,
            historyData: [],
            filteredData: [],
            actionTypeOptions: [],
            userOptions: [],
            dateMasks: {
                input: 'MM/DD/YYYY'
            },
            filters: {
                fromDate: null,
                toDate: null,
                actionType: '',
                userId: '',
                searchText: ''
            },
            selectedRow: null,
            isDetailsOpen: false,
            beforeRows: [],
            afterRows: [],
            rawBefore: '',
            rawAfter: ''
        };
    },
    computed: {
        modalTitle() {
            if (this.moduleType === 'Contract') {
                const k = this.$t('AssignContractHistory');
                return (k && k !== 'AssignContractHistory') ? k : 'Assign Contract History';
            }
            const k = this.$t('AssignBillerHistory');
            return (k && k !== 'AssignBillerHistory') ? k : 'Assign Biller History';
        },
        entityColumnHeader() {
            if (this.moduleType === 'Contract') {
                return (this.$t('BillerName') !== 'BillerName' ? this.$t('BillerName') : 'Biller Name');
            }
            return (this.$t('CONTRACTNAME') !== 'CONTRACTNAME' ? this.$t('CONTRACTNAME') : 'Contract Name');
        },
        searchPlaceholder() {
            const user = (this.$t('User') !== 'User' ? this.$t('User') : 'User');
            const second = this.moduleType === 'Contract'
                ? (this.$t('BillerName') !== 'BillerName' ? this.$t('BillerName') : 'Biller Name')
                : (this.$t('CONTRACTNAME') !== 'CONTRACTNAME' ? this.$t('CONTRACTNAME') : 'Contract Name');
            return `${this.$t('SearchBy') || 'Search by'} ${second} / ${user}`;
        }
    },
    created() {
        this.FetchHistory();
    },
    watch: {
        'filters.fromDate'() {
            this.applyFilters();
        },
        'filters.toDate'() {
            this.applyFilters();
        }
    },
    mounted() {
        this.$nextTick(() => {
            setTimeout(() => {
                this.isShown = true;
            }, 50);
        });
    },
    methods: {
        async FetchHistory() {
            const vm = this;
            vm.isLoading = true;
            try {
                const params = `entityId=${encodeURIComponent(vm.entityId)}&moduleType=${encodeURIComponent(vm.moduleType)}`;
                const response = await DataService.GetAssignBillerHistory(params);
                let result = response && response.data ? response.data : [];
                if (typeof result === 'string') {
                    try { result = JSON.parse(result); } catch (e) { result = []; }
                }
                if (result && typeof result === 'object' && !Array.isArray(result) && result.result !== undefined) {
                    let inner = result.result;
                    if (typeof inner === 'string') {
                        try { inner = JSON.parse(inner); } catch (e) { inner = []; }
                    }
                    result = inner;
                }
                if (!Array.isArray(result)) {
                    result = result ? [result] : [];
                }
                vm.historyData = result;
                vm.hydrateLookups();
                vm.applyFilters();
            } catch (e) {
                console.error('GetAssignBillerHistory error:', e);
                vm.historyData = [];
                vm.filteredData = [];
            } finally {
                vm.isLoading = false;
            }
        },
        hydrateLookups() {
            const KNOWN_ACTIONS = ['Created', 'Updated', 'Deleted', 'Unchanged'];
            const actions = new Set(KNOWN_ACTIONS);
            const usersMap = new Map();
            (this.historyData || []).forEach(r => {
                if (r.ACTION_TYPE) actions.add(String(r.ACTION_TYPE));
                const id = r.CHANGED_BY != null && r.CHANGED_BY !== '' ? String(r.CHANGED_BY) : '';
                const name = r.CHANGED_BY_NAME || r.CHANGED_BY || '';
                if (id) {
                    if (!usersMap.has(id)) usersMap.set(id, String(name));
                }
            });
            this.actionTypeOptions = Array.from(actions);
            this.userOptions = Array.from(usersMap.entries())
                .map(([id, name]) => ({ id, name }))
                .sort((a, b) => String(a.name).localeCompare(String(b.name)));
        },
        applyFilters() {
            const f = this.filters;
            const normalizeText = (val) => String(val == null ? '' : val)
                .replace(/<[^>]+>/g, ' ')
                .replace(/&nbsp;/gi, ' ')
                .replace(/\u00A0/g, ' ')
                .replace(/\s+/g, ' ')
                .trim()
                .toLowerCase();

            const search = normalizeText(f.searchText);
            const searchTokens = search ? search.split(' ').filter(Boolean) : [];

            const from = f.fromDate ? new Date(f.fromDate) : null;
            if (from) from.setHours(0, 0, 0, 0);
            const to = f.toDate ? new Date(f.toDate) : null;
            if (to) to.setHours(23, 59, 59, 999);

            this.filteredData = (this.historyData || []).filter(r => {
                if (f.actionType && String(r.ACTION_TYPE || '') !== String(f.actionType)) return false;
                if (f.userId && String(r.CHANGED_BY || '') !== String(f.userId)) return false;

                if (from || to) {
                    if (!r.CHANGED_AT) return false;
                    const d = new Date(r.CHANGED_AT);
                    if (from && d < from) return false;
                    if (to && d > to) return false;
                }

                if (search) {
                    const hay = [
                        r.CONTRACT_NAME, r.BILLER_NAME, r.ENTITY_NAME,
                        r.CONTRACT_NO,
                        r.CHANGED_BY_NAME, r.CHANGED_BY
                    ].map(normalizeText).filter(v => v).join(' ');

                    if (!hay.includes(search) &&
                        !searchTokens.every(t => hay.includes(t))) {
                        return false;
                    }
                }
                return true;
            });
        },
        ClearFilters() {
            this.filters = { fromDate: null, toDate: null, actionType: '', userId: '', searchText: '' };
            this.applyFilters();
        },
        OpenDetails(row) {
            this.selectedRow = row;
            const before = this.parseValue(row.PREVIOUS_VALUE);
            const after = this.parseValue(row.UPDATED_VALUE);
            this.beforeRows = this.toRows(before);
            this.afterRows = this.toRows(after);
            this.rawBefore = (this.beforeRows.length ? '' : this.stringifyValue(row.PREVIOUS_VALUE));
            this.rawAfter = (this.afterRows.length ? '' : this.stringifyValue(row.UPDATED_VALUE));
            this.isDetailsOpen = true;
        },
        CloseDetails() {
            this.isDetailsOpen = false;
            this.selectedRow = null;
            this.beforeRows = [];
            this.afterRows = [];
            this.rawBefore = '';
            this.rawAfter = '';
        },
        parseValue(v) {
            if (v == null || v === '') return null;
            if (typeof v === 'object') return v;
            const s = String(v).trim();
            if (!s) return null;
            try {
                const parsed = JSON.parse(s);
                if (parsed && typeof parsed === 'object') return parsed;
                return null;
            } catch (e) {
                return null;
            }
        },
        toRows(obj) {
            if (!obj || typeof obj !== 'object') return [];
            if (Array.isArray(obj)) {
                return obj.map((item, idx) => ({
                    key: `[${idx}]`,
                    value: typeof item === 'object' ? JSON.stringify(item) : String(item)
                }));
            }
            return Object.keys(obj).map(k => ({
                key: k,
                value: this.formatFieldValue(k, obj[k])
            }));
        },
        formatFieldValue(key, value) {
            if (value == null) return '';
            if (key === 'StatusId') {
                const n = Number(value);
                if (n === 1001) return 'Active';
                if (n === 1003) return 'Deleted';
                return String(value);
            }
            if (typeof value === 'object') return JSON.stringify(value);
            return String(value);
        },
        isChanged(key) {
            const b = this.beforeRows.find(x => x.key === key);
            const a = this.afterRows.find(x => x.key === key);
            if (!b || !a) return true;
            return String(b.value) !== String(a.value);
        },
        stringifyValue(v) {
            if (v == null) return '';
            if (typeof v === 'object') {
                try { return JSON.stringify(v); } catch (e) { return String(v); }
            }
            return String(v);
        },
        truncate(s, n) {
            if (!s) return '';
            return s.length > n ? s.slice(0, n) + '...' : s;
        },
        entityNameOf(row) {
            // When grouped by Contract, the "other side" of the assignment is
            // a Biller (no contract number applies). When grouped by Biller,
            // the "other side" is a Contract, and we append its contract
            // number (CRM account no) when the SP returns one.
            if (this.moduleType === 'Contract') {
                return row.BILLER_NAME || row.ENTITY_NAME || '';
            }
            const name = row.CONTRACT_NAME || row.ENTITY_NAME || '';
            return this.formatContractWithNumber(name, row.CONTRACT_NO);
        },
        formatContractWithNumber(name, contractNo) {
            const trimmedName = String(name == null ? '' : name).trim();
            const trimmedNo = String(contractNo == null ? '' : contractNo).trim();
            if (!trimmedNo) return trimmedName;
            if (!trimmedName) return trimmedNo;
            return trimmedName + ' (' + trimmedNo + ')';
        },
        actionBadgeClass(action) {
            const a = String(action || '').toUpperCase().trim();
            if (a === 'UNCHANGED' || a === 'NO CHANGES' || a === 'NOCHANGES') {
                return 'bg-secondary';
            }
            if (a.includes('CREATE') || a === 'INSERT' || a === 'ADD' || a === 'ADDED' || a === 'CREATED') {
                return 'bg-success';
            }
            if (a.includes('UPDATE') || a.includes('MODIF') || a === 'EDIT' || a === 'EDITED') {
                return 'bg-warning';
            }
            if (a.includes('DELETE') || a === 'REMOVED' || a === 'REMOVE') {
                return 'bg-danger';
            }
            return 'bg-secondary';
        },
        formatDateTime(dt) {
            if (!dt) return '';
            try {
                if (this.$options && this.$options.filters && this.$options.filters.formatDateTime) {
                    return this.$options.filters.formatDateTime(dt);
                }
            } catch (e) { /* fall through */ }
            try {
                return new Date(dt).toLocaleString();
            } catch (e) {
                return String(dt);
            }
        },
        rowKey(row, index) {
            return row && row.HISTORY_ID != null ? `h_${row.HISTORY_ID}` : `i_${index}`;
        },
        Close() {
            this.isShown = false;
            this.$emit('close');
        }
    }
};
</script>

<style scoped>
.badge {
    font-size: 11px;
    font-weight: 600;
}
.badge-success { background-color: #28a745; color: #fff; }
.badge-warning { background-color: #ffc107; color: #212529; }
.badge-danger  { background-color: #dc3545; color: #fff; }
.badge-secondary { background-color: #6c757d; color: #fff; }
.no-record { padding: 16px 8px; }
</style>
